programs.haiku:
"""Opening quotation marks, reasoning connectives and a few punctuation marks pull this
component negative; end-of-text markers push it slightly positive.

The component's activation is a dense readout spread over thousands of MLP units, and
no simple token rule accounts for most of it (token identity alone explains under 2%
of its variance). So this program only states the clearest pattern, with each class's
average activation:

- An opening quotation mark that introduces speech (right after "says", "say", "said",
  "asked", a colon or a full stop): about -2.6.
- Any other opening quotation mark (often in code, e.g. print("...")): about -0.5.
- A logical connective that starts a clause ("but", "so", "thus", "therefore", "hence",
  "however"): about -2.1.
- A semicolon: about -0.6.
- An end-of-text or chat-turn marker: about +0.9.
- Every other token: 0.
"""

READS = ()

QUOTES = {'"', "'", "“", "‘", "«", "「", "„"}
SPEECH_CUES = {"says", "say", "said", "asked", "replied", ":", "：", ".", "说", "道"}
CONNECTIVES = {"but", "so", "thus", "therefore", "hence", "however"}
SPECIAL = {"<|endoftext|>", "<|im_end|>"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip()
    if tok.lower() in CONNECTIVES:
        value = -2.1
    elif tok in QUOTES:
        value = -2.6 if prev in SPEECH_CUES else -0.5
    elif tok == ";":
        value = -0.6
    elif prefix.token_strings[-1] in SPECIAL:
        value = 0.9
    else:
        value = 0.0
    return carry, value

"""What the component's activation tracks, weakly: where a token sits in its document, what
kind of character it is, and whether the token has already appeared earlier in the document.

The component (direction 2242 of layers.15.mlp.down_proj) is a dense, diffuse readout of the
layer-15 MLP hidden state. Its activation has mean ~0.16 and spread ~0.36 on almost every
token, and no token identity explains it. The consistent patterns are small:
- the first token of a document sits near 0;
- activation rises over the first few dozen tokens of a document, then eases off;
- punctuation and whitespace run a little higher than letters, digits and non-Latin text;
- a token repeated from earlier in the same document runs a little higher.
This program predicts those averages. It explains under 1% of the variance.
"""

READS = ()


def char_class(s):
    t = s.strip()
    if t == "":
        return "newline" if "\n" in s else "space"
    if t.isdigit():
        return "digit"
    if not any(ch.isalnum() for ch in t):
        return "punct"
    if not t.isascii():
        return "other"
    if t.isalpha():
        return "word_sp" if s[0] == " " else "word_nosp"
    return "mixed"


# offset from the average, by kind of token
CLASS_OFFSET = {
    "punct": 0.04,
    "space": 0.05,
    "newline": 0.03,
    "mixed": 0.01,
    "digit": -0.01,
    "word_sp": -0.01,
    "word_nosp": -0.02,
    "other": -0.02,
}


def position_level(pos):
    """Average activation by index within the document (0 = its first token)."""
    if pos == 0:
        return 0.0
    if pos < 8:
        return 0.11
    if pos < 32:
        return 0.15
    if pos < 256:
        return 0.17
    return 0.14


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        pos, seen = 0, frozenset()
    else:
        pos, seen = carry[1] + 1, carry[2]
    repeated = token in seen
    seen = seen | {token}
    value = position_level(pos) + CLASS_OFFSET[char_class(prefix.token_strings[-1])]
    if repeated:
        value += 0.03
    return (doc, pos, seen), value

"""Layer 15 MLP unit 2246 (the component's value), predicted from the words just before it.

What it does: the unit is quiet on most tokens and swings hard on a few kinds of token.
1. Coordinating words ("and", "or", and their translations; a comma in a list) score
   positive. They score most when the word before is a verb or an adjective ("create and",
   "clear and", "useful, expert"), little after a noun ("health and"), and not at all otherwise.
2. Degree words that lead into an adjective ("very", "extremely", "highly", "non", "most",
   "more") score negative.
3. A spaced hyphen " -" right after grep, tail, head or sed (a command-line option such as
   "grep -v", "tail -30") is strongly negative. Other hyphens are about zero.
Everything else is predicted as 0. This is the average of each group, so it is the best
a program of this kind can do; it explains only about 1-2% of the variance. Most of the
unit's swings depend on context this program does not read.
"""
import wordnet

READS = ()

CONJ = {"and", "or", "und", "и", "et", "oder", "ou", "och", "og", "eller", "dan", "y", "e", "&",
        "或", "并", "且", "与"}
COMMA = {","}
DEGREE = {"very", "extremely", "highly", "relatively", "most", "more", "non", "un", "high",
          "really", "quite", "too", "much", "less", "ever", "newly", "low"}
OPTION_COMMANDS = {"grep", "tail", "head", "sed"}


def word_kind(word):
    """'verb', 'adj' (adjective or adverb), 'noun' or 'other', from WordNet."""
    senses = wordnet.parts_of_speech(word) if word.isalpha() else set()
    if "verb" in senses:
        return "verb"
    if senses & {"adjective", "adverb"}:
        return "adj"
    if "noun" in senses:
        return "noun"
    return "other"


CONJ_VALUE = {"verb": 0.3, "adj": 0.5, "noun": 0.05, "other": 0.15}
COMMA_VALUE = {"verb": 0.1, "adj": 0.15, "noun": 0.03, "other": 0.1}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_ids) > 1 else ""
    if word in CONJ:
        value = CONJ_VALUE[word_kind(before)]
    elif word in COMMA:
        value = COMMA_VALUE[word_kind(before)]
    elif word in DEGREE:
        value = -0.35
    elif token == " -" and before in OPTION_COMMANDS:
        value = -6.0
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP hidden unit 2267 (this component reads essentially that unit alone).

It goes negative where a sentence's predicate or complement is about to start, mostly on
linking words in ordinary English prose:
- "is", "was", "are": strongly negative after a noun subject ("The answer is", "The final
  section is"), and most negative when an ordinal or superlative opens the subject ("the
  first book", "the only charge"). Near 0 after pronouns ("It is", "This is", "He was").
- "by" as a means or agent ("ended their remarks by saying", "created by"), and the
  inclusion verbs "include", "comprises", "consists", "involves", which are the most
  negative tokens of all.
- "via", "except", "with", and the colon: mildly negative.
- Commas after an ordinal or superlative noun phrase ("Her first book,"): mildly negative.
"by" written in arithmetic ("multiply by 3") stays near 0.
It is mildly positive on code and math operators ("or", "+", "<<", ".append", "return", "not").

The program is a small table of these words with three context rules: a noun-subject
check (WordNet), an ordinal-or-superlative check, and a math-context check for "by".
"""

import wordnet

READS = ()

ORDINAL = {
    "first", "second", "third", "final", "last", "next", "only", "best", "main",
    "primary", "sole", "single", "earliest", "latest", "biggest", "largest",
}
PRONOUNS = {
    "it", "this", "that", "he", "she", "they", "there", "what", "which", "here",
    "we", "i", "you", "who", "one", "these", "those", "everything", "something",
    "nothing", "everyone", "someone", "anything", "all", "each",
}
INCLUDE = {
    "include", "includes", "including", "included",
    "comprise", "comprises", "comprising", "comprised",
    "consist", "consists", "consisted", "involve", "involves", "involving",
    "contain", "contains", "containing",
}
LINK = {"via": -1.3, "except": -1.3, "with": -0.5, "through": -0.5, ":": -0.7}
CODE_POS = {"or": 0.45, "+": 0.44, "not": 0.3, "<<": 1.3, ".append": 1.35, "return": 0.45}
MATH_CHARS = set("0123456789=+-*/^<>()[]{}_$\\")


def _is_mathy(s):
    """A token that reads as arithmetic or code: contains a digit or a math symbol."""
    return any(ch in MATH_CHARS for ch in s)


def _is_noun(word):
    """A plain word that WordNet lists as a noun, and that is not a pronoun."""
    return word.isalpha() and word not in PRONOUNS and "noun" in wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids[-1]
    n = len(prefix.token_strings)
    # The last 16 tokens of the same document, before the current one.
    lo = max(0, n - 17)
    before = [
        prefix.token_strings[i].strip().lower()
        for i in range(lo, n - 1)
        if prefix.document_ids[i] == doc
    ]
    mathy = sum(_is_mathy(s) for s in before) / max(1, len(before))
    # Did an ordinal or superlative open the current noun phrase (last four tokens)?
    ordinal = any(s in ORDINAL for s in before[-4:])
    prev = before[-1] if before else ""

    if word == "by":
        return carry, (-1.0 if mathy > 0.4 else -3.0)
    if word in INCLUDE:
        return carry, -2.5
    if word in ("is", "was", "are", "were", "be", "being", "been"):
        if ordinal:
            return carry, -3.0
        strength = 1.2 if word in ("is", "was") else 0.6
        return carry, (-strength if _is_noun(prev) else -0.2)
    if word == ",":
        return carry, (-0.5 if ordinal else 0.0)
    if word in LINK:
        return carry, LINK[word]
    if word in CODE_POS:
        return carry, CODE_POS[word]
    if word in ("a", "an"):
        return carry, -0.3
    return carry, 0.0

"""Negation inside directives, as a rule-based guess at what L15 MLP unit 2281 writes.

The component's output (through the unembedding) promotes negation and contrast
continuations ("not", "NOT", "rather than", "不是", "cannot"). Its activations are
largest on a negation word that follows a directive verb in an instruction:
"Do not", "DO NOT", "Don't", "DOES NOT", and more weakly after a modal ("must not",
"should not", "will not") or "but not". Other negation words are weakly positive.
Everything else is predicted as 0. This captures the peaks only; most of the
component's variance is diffuse and not explained by any simple rule.
"""

READS = ()

NEGATION = {"not", "n't", "never", "no", "cannot", "without", "nor"}
SHOUTED_DIRECTIVE = {"Do", "DO", "DOES", "Don", "DON", "Don't"}
DIRECTIVE = {"do", "does", "did", "don", "dont"}
MODALS = {"must", "should", "shall", "will", "would", "can", "could", "may", "might", "but"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word not in NEGATION:
        return None, 0.0
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.3
    before = prefix.token_strings[-2].strip()
    if before in SHOUTED_DIRECTIVE:
        return None, 8.0
    if before.lower() in DIRECTIVE or before.lower() in MODALS:
        return None, 1.0
    return None, 0.3

"""Layer 15 MLP down-projection, component 2288: a "code syntax" feature.

In plain terms: this component is nearly silent in running prose and switches on inside
source code. Its sign depends on what kind of token it is reading:

- assignment and comparison operators (`=`, `==`, `!=`, `:=`, `=>`, `<<`, `:`, `&&`, `||`)
  go strongly negative: the next thing is a value or expression;
- expression keywords (`return`, `throw`, `yield`, `await`, `in`, `instanceof`, `switch`)
  also go negative, for the same reason;
- declaration keywords (`new`, `final`, `static`, `private`, `public`, `struct`, `typedef`,
  `unsigned`, `throws`, `const`) go positive: a type or a name comes next;
- other identifiers go mildly positive, other punctuation mildly negative.

How strongly all of this shows depends on how much code the recent context contains, so the
program measures code density over the last 32 tokens and scales the token values by it.

Why: the component's contribution to the output is tiny, and its activation is large only at
these code tokens. The program captures the token-class pattern and the code gating. It does
not model the context-dependent size of each value, which the recent tokens explain only
weakly.
"""

import re
from collections import deque

READS = ()

WINDOW = 32
ASSIGN = {"=", "==", "!=", "===", ":=", "=>", "<<", ":", "+=", "||", "&&"}
EXPRESSION_WORDS = {"return", "throw", "yield", "await", "in", "instanceof", "switch", "raise"}
DECLARATION_WORDS = {
    "new", "final", "static", "private", "public", "struct", "typedef", "unsigned", "throws", "const",
}
CODE_MARK = re.compile(r"[{}()\[\];=<>_\t]|\.[A-Za-z]|\n\s")
WORD = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")
PUNCT = re.compile(r"[(),;.\[\]{}]+")

W_ASSIGN = -3.5  # operators that introduce a value, inside code
W_EXPRESSION = -3.5  # keywords that introduce an expression, inside code
W_DECLARATION = 2.5  # keywords that introduce a type or name, inside code
W_WORD = 0.5  # any other identifier, inside code
W_PUNCT = -0.3  # other punctuation, inside code


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "marks": deque(maxlen=WINDOW)}
    token = prefix.token_strings[-1]
    carry["marks"].append(1.0 if CODE_MARK.search(token) else 0.0)
    density = sum(carry["marks"]) / len(carry["marks"])  # share of recent tokens that look like code

    text = token.strip()
    if text in ASSIGN:
        value = W_ASSIGN * density
    elif text in EXPRESSION_WORDS:
        value = W_EXPRESSION * density
    elif text in DECLARATION_WORDS:
        value = W_DECLARATION * density
    elif WORD.fullmatch(text):
        value = W_WORD * density
    elif PUNCT.fullmatch(text):
        value = W_PUNCT * density
    else:
        value = 0.0
    return carry, float(value)

"""Normative-judgment detector for one MLP component (layer 15, down_proj, #2291).

What it responds to: words that say what someone should, must or ought to do, and
words that call something right, wrong, a mistake, worth it or deserved, in English and
in other languages. "should" and "ought" (and their translations) give the strongest
responses; "wrong", "mistake", "worth" and "appropriate" medium ones; "must" and "need"
a weaker one. Evaluative adjectives and hedges such as "perhaps" or "maybe" give a
faint one. The word right after a modal ("should NOT", "need TO", "should BE",
"should HAVE") also responds.

The program is a lexicon: each listed word has a fixed value, set from its average
activation on training text. It ignores most context, so it explains only a small part
of the variance: the activation is spread over many ordinary tokens, and its largest
values depend on context the lexicon does not see.
"""

READS = ()

# "should" on its own: the most common strong trigger.
SHOULD = {"should"}
# Other words of strong obligation or deserving, and their translations.
STRONG = {
    "ought", "应该", "sollte", "sollten", "debe", "deben", "deve", "стоит", "值得",
    "deserve", "deserves", "deserved", "worthy", "warranted", "justified", "mistaken",
    "incorrectly", "unnecessarily",
}
# Judgement and obligation words of medium strength.
MID = {
    "wrong", "mistake", "incorrect", "appropriate", "worth", "recommend", "必须", "须",
    "应当", "应", "不要", "别", "doit", "faut", "moet", "darf", "müssen", "unnecessary",
    "improper", "advisable", "preferable", "flawed", "erroneous", "inappropriate",
    "unacceptable", "misleading", "должен", "должны", "nên", "يجب",
}
# Plain necessity words: "must", "need to".
NEED = {"must", "need", "needs"}
# Weaker evaluative words, advisory words and hedges.
WEAK = {
    "good", "better", "correct", "correctly", "important", "importance", "too", "best",
    "supposed", "reasonable", "proper", "properly", "useful", "necessary", "essential",
    "excellent", "effective", "fair", "ideal", "healthy", "great", "bad", "relevant",
    "enough", "needed", "recommended", "why", "shall", "perhaps", "maybe", "think",
    "instead", "нужно", "надо", "лучше",
}
# Modals after which the next word, such as "not", "be", "have" or "to", also responds.
MODALS = {"should", "ought", "must", "need", "needs", "better", "supposed"}
FOLLOWERS = {"not", "be", "have", "to", "'t", "’t"}


def value_of(word):
    if word in SHOULD:
        return 5.0
    if word in STRONG:
        return 6.0
    if word in MID:
        return 3.0
    if word in NEED:
        return 2.0
    if word in WEAK:
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = value_of(word)
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if same_doc and prefix.token_strings[-2].strip().lower() in MODALS and word in FOLLOWERS:
        value += 2.0
    return carry, float(value)

"""Alternatives-and-variety detector for layers.15.mlp.down_proj, component 2297.

In plain terms: this component switches on at words that open a set of several
distinct options, kinds or competitors, and its output pushes the next token
toward plural nouns for such sets ("vendors", "contenders", "designs",
"alternatives"). Its activation is high on:
  - quantifiers that say there are several different ones: several, various,
    numerous, many, multiple, different, other(s), another, most, diverse;
  - other quantity and number words: all, both, each, every, two, three, these,
    some, any, few, more;
  - "of" after a word for a category or amount: "a variety of", "a lot of",
    "types of", "a number of", "dozens of", "many of";
  - "the" after "among" or "compared", and rankings like "the best" or "the largest";
  - plural nouns for groups of rival options: companies, brands, studies, vendors.
It is negative on "of" after titles and roles ("president of", "behalf of"),
and near zero on nearly everything else. The word lists are the groups' mean
activations, rounded; the values are in activation units.

The program reads only the newest token and the one before it, within a document.
It explains only a small share of the variance: most of the component's activation
is diffuse and not tied to any word.
"""

READS = ()

# Quantifiers that announce a plurality of distinct things (strongest).
VARIETY = {
    "several", "various", "numerous", "many", "multiple", "different", "diverse",
    "other", "others", "another", "most", "varying", "assorted", "countless",
}
# Other quantity and number words.
QUANTITY = {
    "all", "both", "each", "every", "two", "three", "four", "these", "one",
    "some", "any", "few", "more",
}
# Plural nouns for groups of rival or alternative options, sources and works.
ALTERNATIVES = {
    "companies", "manufacturers", "brands", "studies", "literature", "firms",
    "providers", "platforms", "apps", "agencies", "vendors", "competitors",
    "alternatives", "options", "approaches", "designs", "organizations",
    "institutions", "products", "sources",
}
# Superlatives and rankings that precede a list of options.
RANKING = {"best", "largest", "biggest", "top", "major", "popular", "leading"}
# Nouns for a category or an amount: "of" after them opens a set of items.
KIND_NOUNS = {
    "variety", "plethora", "lot", "lots", "range", "types", "kinds", "examples",
    "dozens", "hundreds", "thousands", "majority", "number", "comparison",
    "series", "array", "selection", "collection", "couple", "bunch",
    "many", "some", "most", "all", "none", "few", "one", "two", "both", "each",
    "several",
}
# Words after which "the" picks out one member of a group.
GROUP_WORDS = {"among", "amongst", "compared", "choose", "choosing", "evaluate"}
# Titles and roles: "of" after these names a fixed post, not a set of options.
ROLE_NOUNS = {
    "president", "CEO", "behalf", "office", "editor", "manager", "authority",
    "subsidiary",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip() if same_doc else ""
    if word in VARIETY:
        value = 2.5
    elif word in QUANTITY:
        value = 0.9
    elif word in ALTERNATIVES:
        value = 1.5
    elif word in RANKING:
        value = 0.6
    elif word == "of" and before in KIND_NOUNS:
        value = 1.3
    elif word == "the" and before in GROUP_WORDS:
        value = 1.0
    elif word == "of" and before in ROLE_NOUNS:
        value = -0.8
    else:
        value = 0.0
    return carry, value
